<script setup>
import ReplayViewer from './ReplayViewer.vue';
import {ref,computed,onMounted} from 'vue';import {getProgram} from '../catalog.js';import {Drill} from '../drills.js';
function metrics(r){try{return r.interaction?Drill.restore(r.interaction).view():null}catch{return null}}
const replay=ref(null),replayBusy=ref(false);
const data=ref(null),error=ref(''),busy=ref(false),selected=ref(null),note=ref(''),effort=ref(5),search=ref(''),filter=ref('all'),goal=ref(30);
async function api(url,options){const r=await fetch(url,options),v=await r.json();if(!r.ok)throw new Error(v.error||'请求失败');return v}
async function load(){try{data.value=await api('/api/journal');goal.value=data.value.preferences.weeklyMinutes}catch(e){error.value=e.message}}
onMounted(load);
const rows=computed(()=>data.value?.records.filter(r=>(filter.value==='all'||r.kind===filter.value)&&(!search.value||title(r).includes(search.value)))||[]);
const completion=computed(()=>data.value?Math.min(100,Math.round(data.value.weeklySeconds/(data.value.preferences.weeklyMinutes*60)*100)):0);
function title(r){return r.kind==='workout'?(r.title||'分组训练'):(r.interaction?getProgram(r.program)?.title:getProgram(r.program)?.legacyTitle)||r.program}
function open(r){replay.value=null;selected.value=r;note.value=r.reflection?.note||'';effort.value=r.reflection?.effort||5;error.value=''}
async function inspectReplay(){if(!selected.value)return;replayBusy.value=true;try{replay.value=await api('/api/sessions/'+selected.value.id+'/replay')}catch(e){error.value=e.message}finally{replayBusy.value=false}}
async function save(){if(busy.value)return;busy.value=true;try{await api('/api/reflections/'+selected.value.kind+'/'+selected.value.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({effort:effort.value,note:note.value,version:selected.value.reflection?.version||0})});await load();selected.value=null;error.value=''}catch(e){error.value=e.message;await load();if(selected.value)selected.value=data.value.records.find(r=>r.kind===selected.value.kind&&r.id===selected.value.id)||null}finally{busy.value=false}}
async function saveGoal(){if(busy.value)return;busy.value=true;try{await api('/api/preferences',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({weeklyMinutes:goal.value,version:data.value.preferences.version})});await load();error.value=''}catch(e){error.value=e.message;await load()}finally{busy.value=false}}
</script>
<template><section class="progress-workspace"><header><span>训练档案</span><h1>训练记录</h1><p>单次课程与分组训练统一记录，有效时间不包含休息和暂停。</p></header><p v-if="error" role="alert">{{error}}</p><template v-if="data"><div class="journal-stats"><div><span>累计训练</span><b>{{data.totals.sessions}}<small>次</small></b></div><div><span>有效练习</span><b>{{(data.totals.seconds/60).toFixed(1)}}<small>分钟</small></b></div><div><span>交互命中</span><b>{{data.totals.hits}}<small>次</small></b></div></div><div class="journal-overview"><section class="weekly-goal"><span>近七日目标</span><h2>{{(data.weeklySeconds/60).toFixed(1)}} <small>/ {{data.preferences.weeklyMinutes}} 分钟</small></h2><div class="goal-track"><i :style="{width:completion+'%'}"></i></div><p>{{completion}}% · 按北京时间统计</p><form @submit.prevent="saveGoal"><label>自定目标<input v-model.number="goal" type="number" min="5" max="300" step="1" required>分钟</label><button :disabled="busy">保存目标</button></form></section><section class="weekly-chart"><h2>近七日练习时间</h2><div class="daily-bars"><div v-for="d in data.daily" :key="d.day"><span>{{(d.seconds/60).toFixed(1)}}</span><i :style="{height:Math.max(2,d.seconds/Math.max(60,...data.daily.map(d=>d.seconds))*95)+'px'}"></i><small>{{d.day.slice(5)}}</small></div></div></section></div><div class="journal-toolbar"><div><h2>训练历史</h2><p>{{rows.length}} 条记录 · 可记录主观体感与备注</p></div><input v-model="search" aria-label="搜索课程" placeholder="搜索课程"><select v-model="filter" aria-label="训练类型"><option value="all">全部训练</option><option value="session">单次课程</option><option value="workout">分组训练</option></select><a href="/api/personal-export">导出个人档案 JSON ↗</a></div><div class="journal-empty" v-if="!rows.length"><h3>还没有符合条件的训练记录</h3><p>完成并保存一场课程或分组训练后，回来记录体验。</p><RouterLink to="/workout">编排第一次训练 →</RouterLink></div><div class="journal-table"><table v-if="rows.length"><thead><tr><th>课程 / 时间</th><th>有效时间</th><th>目标命中</th><th>主观用力感</th><th>复盘</th></tr></thead><tbody><tr v-for="r in rows" :key="r.kind+r.id"><td><b>{{title(r)}}</b><small>{{new Date(r.startedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</small></td><td>{{r.seconds.toFixed(1)}} 秒</td><td>{{r.hits}}</td><td>{{r.reflection?r.reflection.effort+' / 10':'未填写'}}</td><td><button @click="open(r)">{{r.reflection?'编辑复盘':'记录体验'}}</button></td></tr></tbody></table></div><p class="journal-note">统计口径：有效练习时间、交互目标命中和个人填写的主观用力感。</p></template><p v-else>正在读取训练档案…</p><div v-if="selected" class="reflection-backdrop" @click.self="selected=null"><form class="reflection-panel" @submit.prevent="save"><h2>训练复盘 · {{title(selected)}}</h2><p>{{new Date(selected.startedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</p><div v-if="metrics(selected)" class="journal-drill-summary"><b>本次交互表现</b><p>正确率 {{metrics(selected).accuracy??'—'}}% · 最长连击 {{metrics(selected).bestStreak}}</p><p>误选 {{metrics(selected).mistakes}} · 漏过 {{metrics(selected).missed}} · 正确等待 {{metrics(selected).avoided}}</p><p>{{selected.program==='focus'?'停留完成':'交互响应'}}中位时长 {{metrics(selected).reactionMs??'—'}} ms</p></div><section v-if="selected.kind==='session'" class="replay-inspector"><button type="button" :disabled="replayBusy" @click="inspectReplay">{{replayBusy?'正在重算…':'验证训练回放'}}</button><p v-if="replay">{{replay.status==='verified'?'事件回放与保存的交互统计一致':replay.status==='incomplete'?'事件记录不完整，无法验证全程':replay.reason}}<span v-if="replay.events"> · {{replay.events}} 个事件</span></p><ReplayViewer v-if="replay?.status==='verified'" :journal="replay.replay"/><a v-if="replay?.status==='verified'" :href="'/api/sessions/'+selected.id+'/replay'" target="_blank" rel="noopener">查看回放 JSON ↗</a></section><label>主观用力感 {{effort}} / 10<input v-model.number="effort" type="range" min="1" max="10" step="1"></label><small>1：很轻松 · 10：极费力，仅记录你的感受</small><label>本次体验<textarea v-model="note" maxlength="1000" rows="5" placeholder="节奏、舒适程度或下次想调整的内容"></textarea></label><p v-if="error" role="alert">{{error}}</p><div><button type="button" @click="selected=null" :disabled="busy">返回</button><button :disabled="busy">保存复盘</button></div></form></div></section></template>
<style scoped>
.progress-workspace{padding:8px 0 40px;color:#d9e7f3}.progress-workspace header>span{font-size:10px;letter-spacing:3px;color:#83b9cb}.progress-workspace h1{font-size:30px;font-weight:450;margin:12px 0}.progress-workspace h2{font-size:17px;font-weight:450}.progress-workspace p{color:#859fba;font-size:12px;line-height:1.8}.journal-stats{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #304863;border-bottom:1px solid #304863;padding:25px 0;margin:30px 0}.journal-stats>div{border-right:1px solid #304863;padding-left:25px}.journal-stats>div:first-child{padding:0}.journal-stats>div:last-child{border:0}.journal-stats span{font-size:11px;color:#7f9dbb}.journal-stats b{display:block;font-size:33px;font-weight:400;margin-top:12px}.journal-stats small{font-size:11px;color:#7b9ab7;margin-left:10px}.journal-overview{display:grid;grid-template-columns:1fr 1fr;gap:24px}.journal-overview>section{background:#13273e;border:1px solid #2c4563;border-radius:9px;padding:25px}.weekly-goal>span{font-size:11px;color:#8cafc5}.weekly-goal h2{font-size:32px}.weekly-goal h2 small{font-size:13px;color:#7fa1bf}.goal-track{height:5px;background:#2c425e;border-radius:10px;overflow:hidden;margin-top:24px}.goal-track>i{height:100%;display:block;background:#9bcedb}.weekly-goal label{font-size:11px;color:#89a8c5}.weekly-goal input{width:65px;margin:0 10px}.weekly-goal form{display:flex;align-items:center;gap:15px}.daily-bars{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;height:146px}.daily-bars>div{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;font-size:10px;color:#7298b5;flex:1}.daily-bars i{display:block;width:65%;background:linear-gradient(#b3d9e5,#588aa7);border-radius:3px 3px 0 0;margin:9px 0}.daily-bars small{font-size:10px}.journal-toolbar{display:flex;align-items:center;gap:14px;margin:35px 0 18px}.journal-toolbar>div{flex:1}.journal-toolbar p{margin:8px 0}.journal-toolbar input{width:145px}.journal-toolbar a{font-size:11px;color:#9bc9dc}.journal-table{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left;font-size:12px;min-width:650px}td,th{padding:18px 13px;border-bottom:1px solid #2a405e}th{font-size:11px;color:#779ab9;font-weight:400}td small{display:block;font-size:10px;color:#7092b4;margin-top:9px}td b{font-weight:450}.progress-workspace button,.progress-workspace input,.progress-workspace select,.progress-workspace textarea{background:#162b44;color:#b6d0e5;border:1px solid #3b5676;border-radius:5px;padding:9px 12px;font:inherit;font-size:11px}.progress-workspace button{cursor:pointer}.progress-workspace button:disabled{opacity:.5}.journal-empty{padding:45px 10px;text-align:center}.journal-empty a{color:#b4d7e5;font-size:12px}.journal-note{font-size:10px!important;margin-top:25px}.reflection-backdrop{position:fixed;inset:0;background:#061321bb;display:flex;align-items:center;justify-content:center;z-index:200;padding:20px}.reflection-panel{width:560px;max-height:90vh;overflow:auto;max-width:100%;background:#122b43;border:1px solid #4a6b8d;border-radius:12px;padding:27px}.reflection-panel label{display:block;font-size:12px;color:#a2c0d8;margin-top:24px}.reflection-panel input,.reflection-panel textarea{display:block;width:100%;margin-top:12px}.reflection-panel small{font-size:10px;color:#7398b7}.reflection-panel>div{display:flex;gap:12px;justify-content:flex-end;margin-top:22px}.progress-workspace [role=alert]{color:#efbaad}@media(max-width:750px){.progress-workspace h1{font-size:25px}.journal-overview{grid-template-columns:1fr}.journal-toolbar{flex-wrap:wrap}.journal-toolbar>div{flex-basis:100%}.journal-toolbar a{display:block;width:100%}.journal-stats b{font-size:26px}.journal-stats>div{padding-left:15px}.journal-stats small{font-size:9px;margin-left:5px}.weekly-goal form{flex-wrap:wrap}}

.progress-workspace>header{display:block;height:auto;position:static;padding:0;margin:0;background:transparent;border:0}.journal-toolbar>div{min-width:210px}.journal-toolbar input{flex:0 0 145px}.journal-toolbar select{width:140px;flex:0 0 140px;margin:0}.journal-toolbar>a{white-space:nowrap}.weekly-goal input{display:inline-block}
@media(max-width:750px){.journal-toolbar>div{min-width:0;flex-basis:100%}.journal-toolbar input{width:calc(50% - 8px);flex:1 1 130px}.journal-toolbar select{flex:1 1 130px}.journal-toolbar>a{white-space:normal}}
</style>
